import flask
from flask import request, jsonify, g
import psycopg2
import os
import hashlib
import time

app = flask.Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST, dbname=DB_NAME,
            user=DB_USER, password=DB_PASS
        )
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_session(session_token):
    """Verify session token and return user info."""
    if not session_token:
        return None
    conn = get_db()
    cur = conn.cursor()
    cur.execute("SELECT user_id, role FROM sessions WHERE token = %s AND expires_at > NOW()", (session_token,))
    row = cur.fetchone()
    if row:
        return {'user_id': row[0], 'role': row[1]}
    return None

@app.route('/api/reports/generate', methods=['POST'])
def generate_report():
    """Generate a report based on user-specified filters."""
    session = verify_session(request.headers.get('X-Session-Token'))
    if not session:
        return jsonify({'error': 'unauthorized'}), 401

    data = request.get_json()
    if not data:
        return jsonify({'error': 'invalid request'}), 400

    report_type = data.get('report_type', 'summary')
    department = data.get('department', '')
    date_from = data.get('date_from', '')
    date_to = data.get('date_to', '')
    custom_filter = data.get('custom_filter', '')

    # Build the report query
    base_query = "SELECT id, employee_name, department, salary, hire_date FROM employees WHERE 1=1"

    if department:
        base_query += f" AND department = '{department}'"

    if date_from:
        base_query += f" AND hire_date >= '{date_from}'"

    if date_to:
        base_query += f" AND hire_date <= '{date_to}'"

    # Advanced filter for power users
    if custom_filter and session.get('role') == 'analyst':
        base_query += f" AND ({custom_filter})"

    if report_type == 'summary':
        # Wrap in aggregation
        final_query = f"SELECT department, COUNT(*), AVG(salary) FROM ({base_query}) sub GROUP BY department"
    elif report_type == 'detailed':
        final_query = base_query + " ORDER BY department, employee_name"
    else:
        final_query = base_query

    conn = get_db()
    cur = conn.cursor()
    try:
        cur.execute(final_query)
        rows = cur.fetchall()
    except Exception as e:
        conn.rollback()
        return jsonify({'error': 'query failed', 'detail': str(e)[:200]}), 500

    # Format results
    report_id = hashlib.sha256(f"{time.time()}{session['user_id']}".encode()).hexdigest()[:16]

    return jsonify({
        'report_id': report_id,
        'generated_by': session['user_id'],
        'row_count': len(rows),
        'data': [list(r) for r in rows[:1000]]
    })

@app.route('/api/reports/export', methods=['POST'])
def export_report():
    """Export report data to CSV - uses same query building."""
    session = verify_session(request.headers.get('X-Session-Token'))
    if not session:
        return jsonify({'error': 'unauthorized'}), 401

    data = request.get_json()
    department = data.get('department', '')

    query = f"SELECT * FROM employees WHERE department = '{department}'"

    conn = get_db()
    cur = conn.cursor()
    try:
        cur.execute(query)
        rows = cur.fetchall()
    except Exception as e:
        conn.rollback()
        return jsonify({'error': str(e)[:200]}), 500

    csv_lines = []
    for row in rows[:5000]:
        csv_lines.append(','.join(str(c) for c in row))

    return flask.Response('\n'.join(csv_lines), mimetype='text/csv')

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
